    { f: "Was ist nach Jesus leichter, als dass ein Reicher in das Reich Gottes kommt?", a: ["Dass ein Kamel durch ein Nadelöhr geht", "Dass ein Fisch fliegt", "Dass ein Berg ins Meer fällt", "Dass ein Stein schwimmt"], ref: "Matthäus 19,24", st: 2, ab: "2026-W45" },
    { f: "Welche Tiere hütete der verlorene Sohn in der Fremde?", a: ["Schweine", "Schafe", "Ziegen", "Kamele"], ref: "Lukas 15,15", st: 2, ab: "2026-W45" },
    { f: "Wer ging im Gleichnis am Verletzten vorbei, bevor der Samariter kam?", a: ["Ein Priester und ein Levit", "Zwei römische Soldaten", "Ein Zöllner und ein Fischer", "Zwei Hirten"], ref: "Lukas 10,31-32", st: 2, ab: "2026-W45" },
    { f: "Was tat der Knecht, der ein Talent bekommen hatte?", a: ["Er vergrub es in der Erde", "Er gab es den Armen", "Er verdoppelte es", "Er verlor es"], ref: "Matthäus 25,18", st: 2, ab: "2026-W45" },
    { f: "Was ist im Gleichnis vom Sämann der Same?", a: ["Das Wort Gottes", "Der Glaube", "Das Geld", "Die Liebe"], ref: "Lukas 8,11", st: 2, ab: "2026-W45" },
    { f: "Womit vergleicht Jesus das Himmelreich, für das ein Kaufmann alles verkauft?", a: ["Mit einer kostbaren Perle", "Mit einem Weinberg", "Mit einem Senfkorn", "Mit einem Netz"], ref: "Matthäus 13,45-46", st: 2, ab: "2026-W45" },
    { f: "Wer betete im Gleichnis: „O Gott, sei mir Sünder gnädig!“?", a: ["Der Zöllner", "Der Pharisäer", "Der verlorene Sohn", "Der reiche Kornbauer"], ref: "Lukas 18,13", st: 3, ab: "2026-W45" },
    { f: "Was wollte der reiche Kornbauer im Gleichnis bauen?", a: ["Größere Scheunen", "Einen hohen Turm", "Einen Tempel", "Ein Schiff"], ref: "Lukas 12,18", st: 3, ab: "2026-W45" },
    { f: "Was ist den Sanftmütigen nach den Seligpreisungen verheißen?", a: ["Sie werden das Land erben", "Sie werden Gott schauen", "Sie werden getröstet werden", "Sie werden satt werden"], ref: "Matthäus 5,5", st: 3, ab: "2026-W45" }
